            ld d, a		; Road.cls 108
fn_road_template_tp_zm1:		; Road.cls 109
            db #ED, #30             ; mul d, e: dy * 26 / 256 = dy / 10 [110]
            ld a, d		; Road.cls 111
            inc a		; Road.cls 112
            ld (var_road_crv), a           ; (rw) [113]
            ld a, (var_road_yy)		; Road.cls 114
            ld e, 9		; Road.cls 115
            ld d, a		; Road.cls 116
fn_road_template_tp_zm2:		; Road.cls 117
