            ld a, d		; Road.cls 119
            ld (var_road_camx), a          ; (mw) [120]
            ; the kerbs: 128 - hw - rw .. 128 + hw + rw
            ld a, (var_road_hor)		; Road.cls 122
            ld b, a		; Road.cls 123
            ld a, (var_road_crv)		; Road.cls 124
            add a, b		; Road.cls 125
