            or a		; Road.cls 137
            jr z, fn_road_template_tp_next		; Road.cls 138
            ld b, a		; Road.cls 139
            ld a, 128		; Road.cls 140
            sub b		; Road.cls 141
            ld e, a		; Road.cls 142
            ld a, b		; Road.cls 143
            add a, a		; Road.cls 144
            ld b, a		; Road.cls 145
            ld c, 3		; Road.cls 146
