fn_road_build:		; sub build (asm keyword), Road.cls line 193
            pop hl		; Road.cls 194
            ld a, (hl)		; Road.cls 195
            ld (var_road_hor), a		; Road.cls 196
            pop hl		; Road.cls 197
            ld a, (hl)		; Road.cls 198
            ld (var_road_crv), a		; Road.cls 199
            pop hl		; Road.cls 200
            ld a, (hl)		; Road.cls 201
            ld (var_road_camx), a		; Road.cls 202
            pop hl		; Road.cls 203
            ld e, (hl)		; Road.cls 204
            inc hl		; Road.cls 205
