            ld sp, (ntc_csp)		; Road.cls 212
            ld hl, arr_road_cop		; Road.cls 213
            ld (var_road_cp), hl		; Road.cls 214
            ; the sky: its scroll; the rows from the top (the same vertical scroll all the way down)
            ld b, #16		; Road.cls 216
