            call fn_road_build_bu_emit		; Road.cls 227
            ld b, #70		; Road.cls 228
            xor a		; Road.cls 229
            call fn_road_build_bu_emit		; Road.cls 230
            ; the lines below the horizon: only what changes from the line above is sent
            ld a, (var_road_hor)		; Road.cls 232
            inc a		; Road.cls 233
            ld (var_road_yy), a		; Road.cls 234
            xor a		; Road.cls 235
